class Solution:
    def hasDuplicate(self, nums: List[int]) -> bool:
        h = set()
        for num in nums:
            if num in h:
                return True
            else:
                h.add(num)

        return False

class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        counterS, counterT = {}, {}
        if len(s) != len(t):
            return False

        for ch in range(len(s)):
            counterS[s[ch]] = 1 + counterS.get(s[ch], 0)
            counterT[t[ch]] = 1 + counterT.get(t[ch], 0)

        for c in counterS:
            if counterS[c] != counterT.get(c, 0):
                return False

        return True

