class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        groups = []
        for s in strs:
            placed = False
            for group in groups:
                if Counter(group[0]) == Counter(s):
                    group.append(s)
                    placed = True
                    break
            if not placed:
                groups.append([s])
        return groups

